function bounds(){if(!/^\d{4}-\d{2}-\d{2}$/.test(day.value))throw Error('Choose a valid week-start date.');const start=new Date(day.value+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+7);if(!Number.isFinite(start.getTime()))throw Error('Choose a valid date.');return [+start,+end];}
