function draw(){metrics.replaceChildren();list.replaceChildren();if(!selectedCalendar)return;const total=C.busyMinutes(events,selectedCalendar.start,selectedCalendar.end);add(metrics,'strong',Math.round(total/60*10)/10+' hours booked');add(metrics,'span',events.length+' scheduled events');add(metrics,'span',stale?'STALE · refresh required':'Read-only · '+selectedCalendar.title);if(!events.length)add(list,'p','No events in this selected calendar and week. Other calendars may contain commitments.','helper');for(const e of events){const row=add(list,'article',undefined,'calendar-event');const info=add(row,'div');add(info,'strong',e.title);add(info,'p',format(e)+' · '+(e.busy?'busy':'does not block time')+(e.tentative?' · tentative':''),'helper');const count=C.candidates(e,saved).length;const b=button(row,count?'View context · '+count+' possible past matches':'View context',()=>show(e));b.disabled=stale;}}
function format(e){return e.allDay?new Date(e.start).toLocaleDateString()+' · all day':new Date(e.start).toLocaleString()+' – '+new Date(e.end).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
